const raw = $input.first().json || {};
let envelope = raw;
if (raw.content !== undefined) {
  if (typeof raw.content === 'string') envelope = JSON.parse(raw.content);
  else if (raw.content && raw.content.type === 'Buffer' && Array.isArray(raw.content.data)) envelope = JSON.parse(Buffer.from(raw.content.data).toString('utf8'));
  else if (raw.content && typeof raw.content === 'object') envelope = raw.content;
}
const data = envelope.data || {};
const eventType = envelope.eventType || raw.fields?.routingKey;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (eventType !== 'lead.qualification.requested') throw new Error('Unexpected eventType: ' + String(eventType));
if (envelope.version !== 1) throw new Error('Unsupported qualification event version');
if (!uuid.test(String(envelope.eventId || ''))) throw new Error('eventId must be UUID');
if (!uuid.test(String(data.leadId || ''))) throw new Error('data.leadId must be UUID');
if (!uuid.test(String(data.workflowRunId || ''))) throw new Error('data.workflowRunId must be UUID');
return [{json:{eventId:envelope.eventId,eventType,version:envelope.version,occurredAt:envelope.occurredAt,leadId:data.leadId,workflowRunId:data.workflowRunId,receivedAt:new Date().toISOString()}}];

const event = $node['Code: Validate Event'].json;
const leadResponse = $node['HTTP Request: Get Lead'].json;
const interactionResponse = $node['HTTP Request: Get Interaction Context'].json;
const lead = leadResponse.data || leadResponse;
const interactions = interactionResponse.items || interactionResponse.data?.items || [];
if (!lead.id || lead.id !== event.leadId) throw new Error('Lead response does not match requested leadId');

// Minimize personal data: use company/role/industry attributes, never contact names,
// email, phone, free-form notes, message subjects or message bodies in the AI prompt.
const compactLead = {
  id: lead.id,
  companyName: lead.companyName || null,
  companyWebsite: lead.companyWebsite || null,
  jobTitle: lead.jobTitle || null,
  companySize: lead.companySize ?? null,
  industry: lead.industry || null,
  status: lead.status || null
};
const compactInteractions = interactions.slice(0,20).map(x=>({
  id:x.id,
  type:x.type,
  channel:x.channel,
  occurredAt:x.occurredAt
}));
const context = {lead:compactLead,interactions:compactInteractions};
const prompt = \`You are a B2B lead qualification analyst. Use only supplied company/role and engagement metadata; never infer an individual identity or invent facts.
Return JSON only with: status (QUALIFIED|DISQUALIFIED|NEEDS_REVIEW), confidence (0..1), intent (<=100 chars), reason, nextAction, reviewRequired (boolean).
Use NEEDS_REVIEW when evidence is insufficient or contradictory. Do not calculate HOT/WARM/COLD lead score.
LEAD_CONTEXT:
\${JSON.stringify(context)}\`;
return [{json:{...event,leadId:lead.id,context,prompt}}];

const response = $input.first().json || {};
const prep = $node['Code: Normalize Qualification Input'].json;
const text = response.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('') || '';
if (!text) throw new Error('Gemini returned no candidate text');
const cleaned = text.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
let result; try { result = JSON.parse(cleaned); } catch { throw new Error('Gemini output is not valid JSON'); }
const allowed = ['QUALIFIED','DISQUALIFIED','NEEDS_REVIEW'];
if (!allowed.includes(result.status)) throw new Error('Invalid qualification status');
if (typeof result.confidence !== 'number' || !Number.isFinite(result.confidence) || result.confidence < 0 || result.confidence > 1) throw new Error('Invalid confidence; expected number 0..1');
if (typeof result.reason !== 'string' || !result.reason.trim()) throw new Error('Qualification reason is required');
if (typeof result.reviewRequired !== 'boolean') throw new Error('reviewRequired must be boolean');
return [{json:{...prep,aiResult:{status:result.status,confidence:result.confidence,intent:String(result.intent||'').slice(0,100),reason:result.reason,nextAction:String(result.nextAction||'Manual review').slice(0,500),reviewRequired:result.reviewRequired}}}];

const p = $input.first().json;
const a = p.aiResult;
const reviewRequired = a.reviewRequired || a.status === 'NEEDS_REVIEW' || a.confidence <= 0.80;
const status = reviewRequired && a.status === 'QUALIFIED' ? 'NEEDS_REVIEW' : a.status;
const callbackPayload = {
  leadId:p.leadId, workflowRunId:p.workflowRunId, status,
  intent:a.intent, confidence:a.confidence, reason:a.reason, nextAction:a.nextAction,
  reviewRequired, modelProvider:'google', modelName:$env.GEMINI_MODEL||'gemini-1.5-pro',
  modelVersion:'v1beta', inputSnapshot:p.context, outputSnapshot:a, evaluatedAt:new Date().toISOString()
};
return [{json:{...p,status,reviewRequired,callbackPayload}}];

const policy = $node['Code: Apply Confidence Policy'].json;
const callback = $node['HTTP Request: Qualification Callback'].json;
let receipt = null; try { receipt = $node['HTTP Request: Notify Reviewer'].json; } catch {}
return [{json:{workflow:'T12-WF01',status:'COMPLETED',eventId:policy.eventId,workflowRunId:policy.workflowRunId,leadId:policy.leadId,qualificationStatus:policy.status,confidence:policy.callbackPayload.confidence,reviewRequired:policy.reviewRequired,reviewTaskId:callback.reviewTaskId||null,notificationFound:receipt?.notificationFound??null,completedAt:new Date().toISOString()}}];
